const spaceWorkspaceAccess = `-- name: SpaceWorkspaceAccess :one
SELECT s.id AS resource_id,s.slug,o.id, o.user_id, o.display_name, o.slug, o.bio, o.website_url, o.avatar_url, o.verified, o.created_at, o.updated_at,
 CASE WHEN o.user_id=$1::uuid THEN 'owner' ELSE COALESCE(a.role,'') END::text AS access_role
FROM spaces s JOIN organizers o ON o.id=s.organizer_id
LEFT JOIN space_access a ON a.space_id=s.id AND a.user_id=$1 AND a.revoked_at IS NULL
WHERE (s.id=$2::uuid OR s.slug=$3::text)
AND (o.user_id=$1 OR a.id IS NOT NULL)
`

type SpaceWorkspaceAccessParams struct {
	ActorID    pgtype.UUID `json:"actor_id"`
	ResourceID pgtype.UUID `json:"resource_id"`
	Slug       string      `json:"slug"`
}

type SpaceWorkspaceAccessRow struct {
	ResourceID pgtype.UUID `json:"resource_id"`
	Slug       string      `json:"slug"`
	Organizers Organizers  `json:"organizers"`
	AccessRole string      `json:"access_role"`
}

func (q *Queries) SpaceWorkspaceAccess(ctx context.Context, arg SpaceWorkspaceAccessParams) (SpaceWorkspaceAccessRow, error) {
	row := q.db.QueryRow(ctx, spaceWorkspaceAccess, arg.ActorID, arg.ResourceID, arg.Slug)
	var i SpaceWorkspaceAccessRow
	err := row.Scan(
		&i.ResourceID,
		&i.Slug,
		&i.Organizers.ID,
		&i.Organizers.UserID,
		&i.Organizers.DisplayName,
		&i.Organizers.Slug,
		&i.Organizers.Bio,
		&i.Organizers.WebsiteUrl,
		&i.Organizers.AvatarUrl,
		&i.Organizers.Verified,
		&i.Organizers.CreatedAt,
		&i.Organizers.UpdatedAt,
		&i.AccessRole,
	)
	return i, err
}

